<template><div class="page"><el-card><template #header><div class="card-header"><div><h2>执行与报告</h2><span class="muted">按业务结果定位失败，再查看步骤、截图和录像证据</span></div><el-button :icon="Refresh" @click="store.loadRuns">刷新</el-button></div></template><el-table :data="store.runs" height="calc(100vh - 215px)"><el-table-column prop="runId" label="执行编号" min-width="210"/><el-table-column label="场景" min-width="190"><template #default="{row}">{{scenarioName(row.scenarioId)}}</template></el-table-column><el-table-column label="状态" width="105"><template #default="{row}"><el-tag :type="statusType(row.status)">{{statusLabel(row.status)}}</el-tag></template></el-table-column><el-table-column prop="environment" label="环境" width="100"/><el-table-column label="模式" width="100"><template #default="{row}">{{row.executionMode==='ui'?'UI 模式':row.executionMode}}</template></el-table-column><el-table-column prop="startedAt" label="开始时间" min-width="180"/><el-table-column label="业务结果" min-width="180"><template #default="{row}"><span class="result-summary">成功 {{row.businessSummary?.passedRows||0}} / 失败 {{row.businessSummary?.failedRows||0}}</span></template></el-table-column><el-table-column label="操作" width="100" fixed="right"><template #default="{row}"><el-button type="primary" link @click="detailRef.open(row)">查看详情</el-button></template></el-table-column></el-table></el-card><RunDetailDrawer ref="detailRef"/></div></template>
<script setup>import{onBeforeUnmount,onMounted,ref}from'vue';import{Refresh}from'@element-plus/icons-vue';import{usePlatformStore}from'../stores/platform';import RunDetailDrawer from'../components/RunDetailDrawer.vue';const store=usePlatformStore(),detailRef=ref();let timer;onMounted(()=>{timer=setInterval(()=>{if(store.runs.some(run=>['queued','running'].includes(run.status)))store.loadRuns()},3000)});onBeforeUnmount(()=>clearInterval(timer));function scenarioName(id){return store.scenarios.find(s=>s.id===id)?.name||id}function statusType(s){return({passed:'success',failed:'danger',running:'warning',queued:'info'})[s]||'info'}function statusLabel(s){return({passed:'通过',failed:'失败',running:'执行中',queued:'排队中',skipped:'已跳过'})[s]||s}</script>
